sys_security_acl.script:
var userId = gs.getUserID();
var cardUser = current.getValue('user');

// Own card
if (cardUser == userId) { answer = true; }
else {
    // Look up card user's profile for team/dept checks
    var ep = new GlideRecord('x_2316178_contin_0_employee_profile');
    ep.addQuery('employee', cardUser);
    ep.query();
    if (ep.next()) {
        var team = ep.getValue('team');
        var dept = ep.getValue('department');
        if (team && (ep.team.manager == userId || gs.getUser().isMemberOf(team))) { answer = true; }
        else if (dept && ep.department.dept_head == userId) { answer = true; }
        else { answer = false; }
    } else { answer = false; }
}
